#include <memory>
#include <iostream>

class ClassA {
public:
    void display() const { std::cout << "ClassA instance" << std::endl; }
};

int main() {
    // Create a unique_ptr managing a new ClassA object
    auto ptr = std::make_unique<ClassA>();
    // Access member function via unique_ptr
    ptr->display();
    // No need to delete; automatic cleanup occurs when ptr goes out of scope
    return 0;
}
